cell vauth_bind_validators(cell elected, cell bindings) impure asm "VAUTH_BIND";

;; Whether this chain has activated validator authentication.
;;
;; Read from Config8, which is where activation is decided for everyone: the
;; virtual machine gates the privileged instructions on the same version and
;; capability, and the node reads the same parameter. Deciding from the shape of
;; the message instead would answer a different question -- whether the sender
;; chose to attach bindings -- and a sender does not decide activation.
int validator_auth_active() inline {
  var param = config_param(8);
  if (cell_null?(param)) {
    return false;
  }
  var cs = param.begin_parse();
  if ((cs.slice_bits() != 104) | cs.slice_refs()) {
    return false;
  }
  if (cs~load_uint(8) != 0xc4) {
    return false;
  }
  var version = cs~load_uint(32);
  var capabilities = cs~load_uint(64);
  cs.end_parse();
  return (version >= 16) & ((capabilities & 1024) != 0);
}

;; The three parameters that hold a validator set: previous, current and next.
;;
;; On an active chain exactly one writer may reach them -- the elector's message,
;; where the set passes through the registry before it is installed. Every other
;; writer of a configuration parameter is generic: it takes an index and a cell
;; and carries no bindings, so a set written that way reaches no registry and
;; the chain would hold a current validator set the registry never decided.
;; That is the same fact with two sources, and the second source is the one an
;; attacker who has obtained governance would use, because it is the one with no
;; binding to forge.
;;
;; The tick-tock rotation is not a writer in this sense: it moves cells that are
;; already installed between these three indices and introduces no new set.
int validator_set_param(int param_id) inline {
  return (param_id == 32) | (param_id == 34) | (param_id == 36);
}
cell vauth_registry_state() impure asm "VAUTH_STATE";

;; The registry checkpoint this account carries.
;;
;; Configuration parameter 46 holds the registry state; this holds the
;; checkpoint beside it, and the two are bound by hash when an account is
;; restored. It is read back on every load and written on every store, because
;; an ordinary vote that dropped it would leave the next block with an account
;; nothing can restore -- and a vote has nothing to do with the registry.
global cell registry_checkpoint;

builder store_checkpoint(builder b) inline {
  ifnot (cell_null?(registry_checkpoint)) {
    return b.store_ref(registry_checkpoint);
  }
  return b;
}

registry_checkpoint = null();
if (cs.slice_refs()) {
  registry_checkpoint = cs~load_ref();
} else {
  ;; Genesis seeds the registry parameter and this checkpoint together or it
  ;; seeds neither. So on a chain that has activated the design, an account
  ;; carrying no checkpoint is not one that has yet to migrate; it is one
  ;; whose configuration context can never open. Reading it as the former is
  ;; the only place a second installation route could begin, and it would be
  ;; reachable without the declared one. Refused here rather than seeded
  ;; anywhere.
  throw_if(47, validator_auth_active());
}

;; validator_auth#b3 public_key:SigPubKey weight:uint64 adnl_addr:bits256
  ;;   binding:^ValidatorAuthBinding = ValidatorDescr;
  ;;
  ;; An authenticated chain installs its elected set through VAUTH_BIND, and
  ;; that is the constructor the binder writes. The mask below accepts 0x53 and
  ;; 0x73 only, so without this a validator voting on a bound set is refused
  ;; for the shape of the descriptor the chain itself produced -- and since a
  ;; configuration parameter now needs the normal vote as well as the governing
  ;; quorum, the first of those two doors would be shut on an active chain.
  ;;
  ;; Only the public key and the weight are answered, which is what every
  ;; caller of this function asks for. The address and the binding are left
  ;; unread exactly as 0x73 leaves its address unread: the registry decides
  ;; what a binding means, and reading it here would be a second opinion.
  if (cs.preload_uint(8) == 0xb3) {
    cs~skip_bits(8);
    throw_unless(41, cs~load_uint(32) == 0x8e81278a);
    return (cs~load_uint(256), cs~load_uint(64));
  }

if (validator_auth_active() & validator_set_param(param_id)) {
    ;; A proposal cannot install a validator set on an active chain: it carries
    ;; no bindings and reaches no registry. Declined rather than thrown, like
    ;; every other refusal here -- the proposal has already been removed from
    ;; the vote dictionary by this point, so throwing would leave a proposal
    ;; that fails every vote cast on it forever.
    return (cfg_dict, 0, null());
  }

;; Normal configuration voting has completed for this exact proposal, which now
;; waits for a current-governance operation to finalize it.
;;
;; The marker is the persisted wins field rather than a comparison against the
;; current vote configuration. min_wins comes from configuration parameter 11
;; and a later proposal can change it: compared against a moving threshold, a
;; proposal would stop being terminal when it rose and one that never reached
;; the old threshold would become terminal when it fell. The sentinel cannot be
;; reached by ordinary voting -- a proposal is only stored again while
;; wins < min_wins, and min_wins is a uint8, so a stored non-terminal wins is
;; at most 254.
int awaiting_governance?(slice rest) inline {
  if (rest.null?()) {
    return false;
  }
  var probe = rest;
  probe~load_uint(8);
  return probe~load_uint(8) == 255;
}

;; A proposal that has already completed normal voting takes no further
;; votes and is not reset by a validator-set rotation. Both would change a
;; voting state that is finished; the expiry check above still removes it.
;;
;; Nested rather than one condition: this must not evaluate at all on a chain
;; that has not activated, and the bitwise operator is not a control flow.
if (validator_auth_active()) {
  if (awaiting_governance?(rest)) {
    return (vote_dict, null(), 3);
  }
}

if (validator_auth_active()) {
  if (wins >= min_wins) {
    ;; Normal voting is complete and nothing is installed. The exact proposal
    ;; stays where it is, marked terminal, until a governance operation
    ;; finalizes it; a configuration parameter needs that quorum as well.
    vote_dict~udict_set_builder(256, phash,
      begin_pack_proposal_status(expires, proposal, critical?, voters, weight_remaining, vset_id)
      .store_uint(rounds_remaining, 8)
      .store_uint(255, 8)
      .store_uint(losses, 8));
    return (vote_dict, null(), 3);
  }
}

;; The tick-tock scan reaches this independently of any vote, so a terminal
;; proposal has to be recognised here too: otherwise a rotation reached by a
;; random scan would reset a proposal that voting can no longer change.
if (validator_auth_active()) {
  if (awaiting_governance?(rest)) {
    return (pstatus, false);
  }
}

;; a set may arrive with the registry bindings its members named; a chain
;; that has not activated validator authentication sends none
cell bindings = null();
if (in_msg.slice_refs()) {
  bindings = in_msg~load_ref();
}

;; the registry decides the binding, not this contract and not the
;; sender; a set that cannot be bound is not installed at all
;;
;; Activation is read from Config8, never from whether bindings arrived.
;; On an active chain a set without them is refused outright rather than
;; installed unbound: an unbound set is exactly what an attacker would
;; send, and "the sender omitted the bindings" must not be the reason a
;; set skips the registry.
if (validator_auth_active()) {
  throw_if(45, cell_null?(bindings));
  vset = vauth_bind_validators(vset, bindings);
}

if (action == 0x56417531) {
    ;; apply an authenticated validator registry update
    ;;
    ;; Authority for this action lives in the update itself: the privileged
    ;; instruction validates its authorizations against the registry's own
    ;; governance and refuses otherwise. Requiring the configuration key here in
    ;; addition would let that one key block updates the registry authorized,
    ;; which is the single point of authority this design removes.
    ;;
    ;; The message is therefore unsigned, and is accepted only after the update
    ;; has been applied. A refused update never reaches accept_message, so it is
    ;; dropped inside the gas credit instead of being paid for.
    var update = cs~load_ref();
    var evidence = cs~load_ref();
    ;; A third reference is the exact configuration proposal a governance
    ;; operation finalizes. Which operations take one is decided by the
    ;; instruction, which holds the decoded update: it refuses an operation that
    ;; needs a proposal and has none, and a proposal attached to one that takes
    ;; none. Deciding it here as well would be a second reading of the update.
    cell proposal = null();
    if (cs.slice_refs()) {
      proposal = cs~load_ref();
    }
    cs.end_parse();
    ifnot (cell_null?(proposal)) {
      ;; The second of two gates. Normal configuration voting has already
      ;; completed for this exact proposal and installed nothing; what remains
      ;; is the governing committee's quorum, which the instruction checks, and
      ;; the conditions the vote itself was taken under, which accept_proposal
      ;; checks below exactly as it always has.
      int phash = proposal.cell_hash();
      var (pstatus, found?) = vote_dict.udict_get?(256, phash);
      throw_unless(50, found?);
      var (expires, voted_proposal, critical?, voters, weight_remaining, vset_id, rest) = unpack_proposal_status(pstatus);
      throw_unless(51, expires > now());
      throw_unless(52, awaiting_governance?(rest));
      var finalized = vauth_apply_update(update, evidence);
      ;; The conditions the vote was taken under, decided before the message is
      ;; accepted. They can refuse a finalization whose governance is perfectly
      ;; valid -- the parameter moved since the vote, or it is mandatory, or it
      ;; is critical and this was not a critical vote -- and such a request is
      ;; unsigned and replayable by anyone. Accepting first would make the
      ;; configuration account pay, over and over, for a request that could
      ;; never have succeeded. Refusing here leaves it inside the credit the
      ;; external sender already had.
      (cfg_dict, var param_id, var param_val) = accept_proposal(cfg_dict, proposal, critical?);
      throw_unless(53, param_id);
      registry_checkpoint = vauth_registry_state();
      accept_message();
      stored_seqno = (stored_seqno + 1) % (1 << 32);
      ;; Consumed so a finalization that succeeds cannot be run twice. One the
      ;; conditions refused threw above and committed nothing at all, so the
      ;; parameter, the registry and the proposal are all left as they were and
      ;; the proposal is still awaiting governance for a later attempt.
      vote_dict~udict_delete?(256, phash);
      ;; Both parameters are set in this dictionary rather than through
      ;; set_conf_param, which rewrites the account from get_data(): the store
      ;; below would put this dictionary back over it, and the registry would be
      ;; the one thing the finalization did not keep.
      cfg_dict~idict_set_ref(32, 46, finalized);
      store_data(cfg_dict, stored_seqno, public_key, vote_dict);
      commit();
      (cfg_dict, public_key) = perform_proposed_action(cfg_dict, public_key, param_id, param_val);
      store_data(cfg_dict, stored_seqno, public_key, vote_dict);
      return ();
    }
    var registry = vauth_apply_update(update, evidence);
    ;; The checkpoint for exactly the state just staged, so the account and
    ;; parameter 46 describe the same registry. Taken from the instruction
    ;; rather than rebuilt here: the contract has no way to derive one.
    registry_checkpoint = vauth_registry_state();
    accept_message();
    stored_seqno = (stored_seqno + 1) % (1 << 32);
    store_data(cfg_dict, stored_seqno, public_key, vote_dict);
    set_conf_param(46, registry);
    commit();
    return ();
  }

;; A block with no registry message still has native state to persist. The
;; prefix this block begins from already carries the transitions that fall
;; due at this coordinate; if nothing writes it back, parameter 46 keeps
;; naming them as due at a coordinate that has passed, and the next block
;; cannot open a registry at all.
;;
;; Both homes come out of one cell. The checkpoint's first reference is the
;; registry state that parameter 46 holds, so the account and the parameter
;; cannot end up describing different registries here: there is one value.
;;
;; The dictionary is edited in place rather than through set_conf_param,
;; which rewrites the account from get_data() and would be undone by the
;; store_data below.
if (validator_auth_active()) {
  registry_checkpoint = vauth_registry_state();
  var rcs = registry_checkpoint.begin_parse();
  rcs~skip_bits(80);
  cfg_dict~idict_set_ref(kl, 46, rcs~load_ref());
}

