;; The registry identity each elected member named, carried beside the set to
;; the configuration contract. It is filled where both the staking account and
;; the named identity are known, and it is never judged here: whether an
;; identity really belongs to that account is the registry's answer, not this
;; contract's.
global cell elector_bindings;


;; Whether this chain has activated validator authentication.
;;
;; Read from Config8, the same version and capability the virtual machine gates
;; the privileged instructions on and the node reads. What a stake or an
;; election carries is never allowed to answer this: a sender would then be
;; deciding when the chain starts requiring identities.
int validator_auth_active() inline {
  var param = config_param(8);
  if (cell_null?(param)) {
    return false;
  }
  var cs = param.begin_parse();
  if ((cs.slice_bits() != 104) | cs.slice_refs()) {
    return false;
  }
  if (cs~load_uint(8) != 0xc4) {
    return false;
  }
  var version = cs~load_uint(32);
  var capabilities = cs~load_uint(64);
  cs.end_parse();
  return (version >= 16) & ((capabilities & 1024) != 0);
}

ifnot (cell_null?(elector_bindings)) {
  ;; wrapped the way every other dictionary crossing this boundary is, so the
  ;; reader has one shape to know rather than one per sender
  msg = msg.store_ref(begin_cell().store_dict(elector_bindings).end_cell());
}

;; a stake may name the registry identity it is for; one that does not is a
;; stake on a chain that has not activated validator authentication
int named_identity = 0;
if (cs.slice_bits()) {
  named_identity = cs~load_uint(256);
}
if (validator_auth_active() & (named_identity == 0)) {
  ;; an active chain has no use for a stake naming no identity: it could
  ;; never be selected, and leaving it in members would strand the stake
  cs.end_parse();
  return return_stake(s_addr, query_id, 7);
}

;; a record that names an identity carries it in a reference; an active
;; chain reads it, because a member without one cannot be selected
int named_identity = 0;
if (cs.slice_refs()) {
  named_identity = cs~load_ref().begin_parse().preload_uint(256);
}

;; src_addr was read without consuming it; step over it and the adnl
;; address to reach the identity this member named, if it named one
val~load_uint(256);
val~load_uint(256);
if (auth_active & val.slice_refs()) {
  elector_bindings~udict_set_builder(16, i, begin_cell()
    .store_uint(src_addr, 256)
    .store_uint(val~load_ref().begin_parse().preload_uint(256), 256));
}

;; A stake that named no identity was excluded from selection above. Its
;; record is still in members and nothing else will ever pay it back, so it
;; is refunded here -- after a successful election, and only here. Refunding
;; during the scan would pay twice: a failed election leaves members intact
;; and the next arriving stake makes the election retryable.
if (auth_active) {
  var refund_key = -1;
  do {
    (refund_key, var rec, var found) = members.udict_get_next?(256, refund_key);
    if (found) {
      var refund_stake = rec~load_tomis();
      rec~load_uint(32);
      rec~load_uint(32);
      var refund_addr = rec~load_uint(256);
      rec~load_uint(256);
      ifnot (rec.slice_refs()) {
        credits~credit_to(refund_addr, refund_stake);
      }
    }
  } until (~ found);
}

;; a record that names an identity carries it in a reference; this walk
;; only has to reach the end of the record, not to use what it finds
if (cs.slice_refs()) {
  cs~load_ref();
}
